package com.ruoyi.warehouse.inbound;

import com.ruoyi.warehouse.catalog.WarehouseCatalog;
import com.ruoyi.warehouse.data.*;
import com.ruoyi.warehouse.security.WarehouseFields;
import com.ruoyi.warehouse.support.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

public class SharedMasterTest {
    InboundServiceTest f;MasterDataService master;
    @BeforeEach void setup(){f=new InboundServiceTest();f.database();master=new MasterDataService(new WarehouseCatalog(),f.records,f.scope,mock(WarehouseFields.class));f.jdbc.execute("CREATE ALIAS JSON_EXTRACT FOR 'com.ruoyi.warehouse.inbound.SharedMasterTest.extract'");f.jdbc.execute("CREATE ALIAS JSON_UNQUOTE FOR 'com.ruoyi.warehouse.inbound.SharedMasterTest.unquote'");}
    public static String extract(String json,String path){return WarehouseJson.text(WarehouseJson.map(json),path.substring(2));}
    public static String unquote(String value){return value;}
    Map<String,Object> save(String kind,String id,Map<String,Object> data){return f.tx.execute(s->master.save(kind,id,data));}
    Map<String,Object> supplier(){return save("suppliers",null,Map.of("name","Acme","contact","Casey","email","casey@example.test"));}
    Map<String,Object> forecast(String supplier){var data=new LinkedHashMap<String,Object>(Map.of("requestId",UUID.randomUUID().toString(),"reference","SUP-"+UUID.randomUUID(),"client","client","warehouse","warehouse","deliveryType","LCL Boxes","lines",List.of(Map.of("product","product","quantity",1))));if(supplier!=null)data.put("supplierId",supplier);return data;}
    long count(String query){return f.jdbc.queryForObject(query,Long.class);}
    @Test void supplierContactsValidateAndSharedWritesRequireAdministrator(){var row=supplier();assertEquals(true,row.get("active"));assertThrows(WarehouseException.class,()->save("suppliers",null,Map.of("name","Bad","email","not an email")));assertThrows(RuntimeException.class,()->save("suppliers",null,Map.of("name","acme")));doThrow(WarehouseException.forbidden()).when(f.scope).requireAdministrator();assertThrows(WarehouseException.class,()->save("suppliers",null,Map.of("name","Another")));assertThrows(WarehouseException.class,()->save("suppliers",String.valueOf(row.get("id")),Map.of("_version",1,"contact","Other")));assertThrows(WarehouseException.class,()->f.tx.execute(s->{master.delete("suppliers",String.valueOf(row.get("id")),1);return null;}));}
    @Test void builtinManualAndEmptyActiveStateCannotBeCreated(){assertThrows(WarehouseException.class,()->save("channels",null,Map.of("name","manual")));assertThrows(WarehouseException.class,()->save("channels",null,Map.of("name","Retail","active","")));assertThrows(WarehouseException.class,()->save("channels",null,Map.of("name","X".repeat(101))));}
    @Test void referencedChannelNameIsProtectedWhileDeactivationIsAllowed(){var channel=save("channels",null,Map.of("name","Retail"));String id=String.valueOf(channel.get("id"));f.jdbc.update("INSERT INTO wh_reference VALUES('product',?,'channelId')",id);assertThrows(WarehouseException.class,()->save("channels",id,Map.of("_version",1,"name","Renamed")));assertEquals(false,save("channels",id,Map.of("_version",1,"active",false)).get("active"));assertThrows(WarehouseException.class,()->f.tx.execute(s->{master.delete("channels",id,2);return null;}));}
    @Test void legacyTextPricingAlsoProtectsChannelName(){var channel=save("channels",null,Map.of("name","Retail"));f.tx.executeWithoutResult(s->f.records.write("channelTiers","legacy",Map.of("client","client","channel","Retail"),null,"retail","client"));assertThrows(WarehouseException.class,()->save("channels",String.valueOf(channel.get("id")),Map.of("_version",1,"name","Other")));}
    @Test void unusedChannelCanBeRenamedAndDeleted(){var row=save("channels",null,Map.of("name","Retail"));String id=String.valueOf(row.get("id"));var renamed=save("channels",id,Map.of("_version",1,"name","Wholesale"));assertEquals("Wholesale",renamed.get("name"));f.tx.executeWithoutResult(s->master.delete("channels",id,2));assertEquals(0,count("SELECT COUNT(*) FROM wh_record WHERE kind='channels'"));}
    @Test void supplierAssignmentRetainsNameAndDoesNotCopyContactDetails(){var supplier=supplier();String sid=String.valueOf(supplier.get("id"));var body=forecast(sid);var asn=f.tx.execute(s->f.service.save(null,body));assertEquals("Acme",asn.get("supplierName"));assertFalse(WarehouseJson.write(asn).contains("casey@example.test"));assertEquals(1,count("SELECT COUNT(*) FROM wh_reference WHERE target_id='"+sid+"'"));save("suppliers",sid,Map.of("_version",1,"name","Acme revised","active",false));assertThrows(WarehouseException.class,()->f.tx.execute(s->f.service.save(null,forecast(sid))));assertEquals(asn.get("id"),f.tx.execute(s->f.service.save(null,body)).get("id"));var edit=forecast(null);edit.put("_version",asn.get("_version"));edit.put("reference",asn.get("reference"));var kept=f.tx.execute(s->f.service.save(String.valueOf(asn.get("id")),edit));assertEquals("Acme",kept.get("supplierName"));assertThrows(RuntimeException.class,()->f.tx.execute(s->{master.delete("suppliers",sid,2);return null;}));}
    @Test void explicitSupplierClearRemovesOnlyTheAssociation(){var supplier=supplier();var asn=f.tx.execute(s->f.service.save(null,forecast(String.valueOf(supplier.get("id")))));var edit=forecast("");edit.put("_version",asn.get("_version"));edit.put("reference",asn.get("reference"));var updated=f.tx.execute(s->f.service.save(String.valueOf(asn.get("id")),edit));assertFalse(updated.containsKey("supplierId"));assertFalse(updated.containsKey("supplierName"));assertEquals(0,count("SELECT COUNT(*) FROM wh_reference WHERE field_name='supplierId'"));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='suppliers'"));}
    @Test void channelPricingRequiresKnownActiveChannelAndRetainsExistingRuleIdentity(){var row=save("channels",null,Map.of("name","Retail"));var data=new LinkedHashMap<String,Object>(Map.of("channel","Retail"));var refs=new LinkedHashMap<String,String>();f.tx.executeWithoutResult(s->SharedMasterReferences.channelPricing(f.records,data,null,refs));assertEquals(row.get("id"),refs.get("channelId"));save("channels",String.valueOf(row.get("id")),Map.of("_version",1,"active",false));assertThrows(WarehouseException.class,()->f.tx.executeWithoutResult(s->SharedMasterReferences.channelPricing(f.records,data,null,new HashMap<>())));assertDoesNotThrow(()->f.tx.executeWithoutResult(s->SharedMasterReferences.channelPricing(f.records,data,Map.of("channel","Retail"),new HashMap<>())));assertThrows(WarehouseException.class,()->f.tx.executeWithoutResult(s->SharedMasterReferences.channelPricing(f.records,Map.of("channel","Unknown"),null,new HashMap<>())));}
}
